public class Main {
    interface Discount {
        int apply(int price);
    }

    static class NoDiscount implements Discount {
        public int apply(int price) {
            return price;
        }
    }

    static class TenPercent implements Discount {
        public int apply(int price) {
            return price - price / 10;
        }
    }

    static class Flat50 implements Discount {
        public int apply(int price) {
            return Math.max(0, price - 50);
        }
    }

    static int checkout(int price, Discount discount) {
        return discount.apply(price);
    }

    public static void main(String[] args) {
        System.out.println(checkout(200, new NoDiscount()));
        System.out.println(checkout(200, new TenPercent()));
        System.out.println(checkout(200, new Flat50()));
    }
}
